import fs from "fs";
import path from "path";
import { fileURLToPath } from "url";
import { logger } from "./logger.js";

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

// Embedded production-grade fallbacks (673 DPI at print size)
const FALLBACK_LOGO_WHITE_BASE64 = "";
const FALLBACK_LOGO_COLOR_BASE64 = "";

let cachedWhiteBuffer: Uint8Array | null = null;
let cachedColorBuffer: Uint8Array | null = null;

export async function getOrionKidsLogoBytes(variant: "white" | "color" = "white"): Promise<Uint8Array> {
  if (variant === "white" && cachedWhiteBuffer) return cachedWhiteBuffer;
  if (variant === "color" && cachedColorBuffer) return cachedColorBuffer;

  const filename = variant === "white" ? "orionkids-logo-white-opt.png" : "orionkids-logo-color-opt.png";
  const unoptFilename = variant === "white" ? "orionkids-logo-white.png" : "orionkids-logo-color.png";

  const searchPaths = [
    path.resolve(process.cwd(), "assets", filename),
    path.resolve(process.cwd(), "src/assets", filename),
    path.resolve(process.cwd(), "dist/assets", filename),
    path.resolve(__dirname, "../../assets", filename),
    path.resolve(__dirname, "../assets", filename),
    path.resolve(__dirname, "./assets", filename),
    path.resolve(process.cwd(), "assets", unoptFilename),
    path.resolve(process.cwd(), "src/assets", unoptFilename),
  ];

  for (const p of searchPaths) {
    try {
      if (fs.existsSync(p)) {
        const buf = fs.readFileSync(p);
        if (buf && buf.length > 0) {
          const uint8 = new Uint8Array(buf);
          if (variant === "white") cachedWhiteBuffer = uint8;
          else cachedColorBuffer = uint8;
          return uint8;
        }
      }
    } catch (e) {
      // continue search
    }
  }

  // Resilient fallback to embedded base64
  logger.debug({ variant }, "Loading OrionKids logo from embedded fallback buffer");
  const b64 = variant === "white" ? FALLBACK_LOGO_WHITE_BASE64 : FALLBACK_LOGO_COLOR_BASE64;
  const fallbackBuf = new Uint8Array(Buffer.from(b64, "base64"));
  if (variant === "white") cachedWhiteBuffer = fallbackBuf;
  else cachedColorBuffer = fallbackBuf;
  return fallbackBuf;
}
